class LinkedList:
    class Node:
        def __init__(self, v):
            self.v = v
            self.next = None

    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def push_front(self, v):
        old_head = self.head
        new_head = LinkedList.Node(v)
        new_head.next = old_head
        self.head = new_head
        if self.size == 0:
            self.tail = new_head
        self.size += 1

    def push_back(self, v):
        new_node = LinkedList.Node(v)
        if self.size == 0:
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.next = new_node
            self.tail = new_node
        self.size += 1

    def pop_front(self):
        if self.size == 0:
            return None
        item = self.head.v
        self.head = self.head.next
        if self.size == 1:
            self.tail = None
        self.size -= 1
        return item

    def __getitem__(self, i):
        if i >= self.size or i < 0:
            return None
        cur = self.head
        while(i > 0):
            cur = cur.next
            i -= 1
        return cur

    def __len__(self):
        return self.size

    def remove(self, v):
        cur = self.head
        prev = None
        while(True):
            if cur == None:
                return False
            elif (cur.v) == v:
                if prev != None:
                    prev.next = cur.next
                else:
                    self.head = cur.next
                    if len == 1:
                        self.tail = None
                return True
            prev = cur
            cur = cur.next

    def __delitem__(self, pos=-1):
        cur = self.head
        prev = None
        for i in range(self.size+pos):
            if pos > 0:
                if i < 0:
                    break
            if cur == None:
                return False
            for i in range(pos):
                if pos < 0:
                    break
                cur = cur.next
            if cur == None:
                return False
            prev = cur
            cur = cur.next

        if prev != None:
            prev.next = cur.next
            if prev.next == None:
                self.tail = prev
        else:
            self.head = cur.next

        cur.next = None
        self.size -= 1


